DECLARE @Today DATE=CAST(DATEADD(minute,420,SYSUTCDATETIME()) AS DATE);
DECLARE @Monday DATE=DATEADD(day,-(DATEDIFF(day,'19000101',@Today)%7),@Today);
DECLARE @Owner INT=(SELECT TOP 1 MaNhanVien FROM NhanVien WHERE SoDienThoai='0900000000');
DECLARE @d INT=0;
WHILE @d<6 BEGIN
DECLARE @Day DATE=DATEADD(day,@d,@Monday);
IF NOT EXISTS(SELECT 1 FROM LichPhanCa pc JOIN NhanVien n ON pc.MaNhanVien=n.MaNhanVien WHERE n.SoDienThoai='0901000001' AND pc.NgayLamViec=@Day) INSERT INTO LichPhanCa(MaChiNhanh,MaNhanVien,NgayLamViec,BatDauLam,KetThucLam,ViTriLamViec,GhiChu,NguoiTao,NguoiCapNhat) SELECT MaChiNhanh,MaNhanVien,@Day,DATEADD(minute,-420,DATEADD(minute,1080,CAST(@Day AS DATETIME2))),DATEADD(minute,-420,DATEADD(minute,1320,CAST(@Day AS DATETIME2))),N'Quản lý ca',N'Lịch mẫu tuần hiện tại',@Owner,@Owner FROM NhanVien WHERE SoDienThoai='0901000001';
IF NOT EXISTS(SELECT 1 FROM LichPhanCa pc JOIN NhanVien n ON pc.MaNhanVien=n.MaNhanVien WHERE n.SoDienThoai='0902000001' AND pc.NgayLamViec=@Day) INSERT INTO LichPhanCa(MaChiNhanh,MaNhanVien,NgayLamViec,BatDauLam,KetThucLam,ViTriLamViec,GhiChu,NguoiTao,NguoiCapNhat) SELECT MaChiNhanh,MaNhanVien,@Day,DATEADD(minute,-420,DATEADD(minute,360,CAST(@Day AS DATETIME2))),DATEADD(minute,-420,DATEADD(minute,720,CAST(@Day AS DATETIME2))),N'Thu ngân',N'Lịch mẫu tuần hiện tại',@Owner,@Owner FROM NhanVien WHERE SoDienThoai='0902000001';
